class HardwareUnit {
    const int serial_id;
    int& current_state;
    double initialization_time;

public:
    // MIL ensures const/reference members are initialized correctly.
    // Initialization order follows member declaration order, not MIL order.
    HardwareUnit(int id, int& state_ref, double setup_time)
        : current_state(state_ref), // Second declared, initialized second
          serial_id(id),            // First declared, initialized first
          initialization_time(setup_time)
    {}
};
